BEGIN;
CREATE OR REPLACE FUNCTION public.count_user_daily_reports(p_user_id uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT COUNT(*)::integer FROM public.reports WHERE user_id=p_user_id AND p_user_id=auth.uid() AND created_at >= (NOW() AT TIME ZONE 'Africa/Abidjan')::date::timestamptz; $$;
REVOKE EXECUTE ON FUNCTION public.count_user_daily_reports(uuid) FROM public,anon;
GRANT EXECUTE ON FUNCTION public.count_user_daily_reports(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_active_outage_count() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND status='active' AND report_category='outage'; $$;
CREATE OR REPLACE FUNCTION public.get_commune_active_durations() RETURNS TABLE(commune text,service_type text,oldest_start timestamptz,longest_hours numeric,active_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT r.commune,r.service_type,MIN(COALESCE(r.start_time,r.created_at)),ROUND(EXTRACT(EPOCH FROM(now()-MIN(COALESCE(r.start_time,r.created_at))))/3600,1),COUNT(r.id) FROM public.reports r WHERE r.validated=true AND r.status='active' AND r.report_category='outage' AND r.commune IS NOT NULL GROUP BY r.commune,r.service_type; $$;
CREATE OR REPLACE FUNCTION public.get_commune_impact_stats(p_commune text) RETURNS json LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT json_build_object('total_reports',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND lower(commune)=lower(p_commune)),'resolved_reports',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND lower(commune)=lower(p_commune) AND status='resolved'),'infra_reports',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND lower(commune)=lower(p_commune) AND report_category='infrastructure'),'reports_last_7',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND lower(commune)=lower(p_commune) AND created_at>=NOW()-INTERVAL '7 days'),'reports_prev_7',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND lower(commune)=lower(p_commune) AND created_at>=NOW()-INTERVAL '14 days' AND created_at<NOW()-INTERVAL '7 days')); $$;
CREATE OR REPLACE FUNCTION public.get_landing_stats() RETURNS json LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT json_build_object('total_reports',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true),'resolved_reports',(SELECT COUNT(*)::integer FROM public.reports WHERE validated=true AND status='resolved'),'total_users',(SELECT COUNT(*)::integer FROM public.profiles)); $$;
CREATE OR REPLACE FUNCTION public.get_landing_nearby_reports(p_lat double precision,p_lon double precision,p_rayon_m double precision DEFAULT 2000,p_limit integer DEFAULT 5) RETURNS TABLE(id uuid,service_type text,report_category text,commune text,quartier text,description text,created_at timestamptz,verifications integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','extensions' AS $$ SELECT r.id,r.service_type,r.report_category,r.commune,r.quartier,left(r.description,200),r.created_at,r.verifications FROM public.reports r WHERE r.validated=true AND r.status='active' AND r.geom IS NOT NULL AND extensions.ST_DWithin(r.geom::extensions.geography,extensions.ST_SetSRID(extensions.ST_MakePoint(p_lon,p_lat),4326)::extensions.geography,least(greatest(p_rayon_m,100),2000)) ORDER BY extensions.ST_Distance(r.geom::extensions.geography,extensions.ST_SetSRID(extensions.ST_MakePoint(p_lon,p_lat),4326)::extensions.geography) ASC LIMIT least(greatest(p_limit,1),20); $$;
CREATE OR REPLACE FUNCTION public.find_similar_reports(p_commune text,p_quartier text,p_service_type text,p_report_category text DEFAULT 'outage') RETURNS TABLE(id uuid,service_type text,description text,quartier text,verifications integer,created_at timestamptz,start_time timestamptz,user_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT r.id,r.service_type,left(r.description,120),r.quartier,r.verifications,r.created_at,r.start_time,NULL::uuid FROM public.reports r WHERE r.validated=true AND r.status='active' AND r.commune=p_commune AND r.service_type=p_service_type AND r.report_category=p_report_category AND (p_quartier='' OR r.quartier ILIKE '%'||p_quartier||'%') AND r.created_at>now()-interval '48 hours' ORDER BY r.verifications DESC,r.created_at DESC LIMIT 5; $$;
COMMIT;
